<h1><?= te('Payroll review and export') ?></h1><p class="sub"><?= te('Approved sheets only. Exporting does not mark a salary paid. ADP RUN output is a draft adapter that must be checked against the customer\'s enabled import template and earning codes.') ?></p><form class="card row" method="get"><input type="date" name="week" value="<?= e($week) ?>"><button class="btn"><?= te('Open pay week') ?></button></form><p><a class="btn" href="/payroll-export?week=<?= e($week) ?>&export=review"><?= te('Review CSV') ?></a> <a class="btn ghost" href="/payroll-export?week=<?= e($week) ?>&export=adp_run"><?= te('ADP RUN draft CSV') ?></a></p><div class="card"><a href="https://support.adp.com/adp_payroll/content/hybrid/%40runcomplete/doc/pdf/FSDDenroll.pdf" target="_blank" rel="noopener"><?= te('ADP direct-deposit authorization form') ?></a><p class="muted"><?= te('Submit banking authorization through the approved payroll process. The platform does not initiate transfers or calculate withholding.') ?></p></div><?php foreach($sheets as $s): ?><div class="card"><h2><?= e($s['full_name']) ?> · <?= e($s['status']) ?></h2><p><?= e($s['adp_employee_id'].' · '.$s['employment_type'].' · '.$s['payment_method']) ?></p><?php if($s['status']==='approved'): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="timesheet_id" value="<?= (int)$s['id'] ?>"><select name="method"><option value="direct_deposit"><?= te('direct_deposit') ?></option><option value="check"><?= te('check') ?></option><option value="cash"><?= te('cash') ?></option></select><input name="reference" required placeholder="<?= te('ADP / transfer / cheque / cash receipt reference') ?>"><button class="btn"><?= te('Record confirmed payment') ?></button></form><?php endif; ?></div><?php endforeach; ?>